//! Immutable-original entire reports, original bytes and exotic line numbering.
use crate::lint::Registry;
#[path="../fixtures/original_policies/cache.rs"]mod original;
#[path="../fixtures/native-cache/fixture.rs"]mod fixture;
fn record(outcome:&crate::run::Outcome)->serde_json::Value{serde_json::json!({"sites":outcome.run.sites,"notes":outcome.run.notes,"allow_used":outcome.allow_used,"failed":outcome.failed,"text":outcome.text})}
#[test]fn cache_unique_policy_preserves_full_original_utf8_ignore_splitlines_first_match_allow_and_report(){for case in fixture::CASES{let root=crate::test_scratch::dir(&format!("cache-original-{case}"));for(relative,bytes)in fixture::files(case).unwrap(){let file=root.join(relative);std::fs::create_dir_all(file.parent().unwrap()).unwrap();std::fs::write(file,bytes).unwrap();}let options=crate::run::Options{root:root.clone(),lints:vec!["cache".into()],raw:true,no_cache:true,..Default::default()};let mut registry=Registry::default();original::register(&mut registry);let old=crate::run::Engine::new(registry,options.clone()).unwrap();let current=crate::run::Engine::new(crate::run::registry(),options).unwrap();let expected=old.run_one(old.reg.lints[0].as_ref());let actual=current.run_one(current.reg.lints.iter().find(|lint|lint.meta().name=="cache").unwrap().as_ref());assert_eq!(record(&actual),record(&expected),"entire original cache {case}");assert!(!expected.run.sites.is_empty());if *case=="hidden_exempt"{assert!(expected.run.sites.iter().any(|site|site.rel=="code/.hidden/cache.dm"));assert!(!expected.run.sites.iter().any(|site|site.rel.starts_with("code/exempt/")),"actual configured prefix must be excluded by both original and native policy");}println!("CACHE_WHOLE_ORIGINAL={}",serde_json::json!({"case":case,"record":record(&actual)}));}}
#[cfg(feature="native-policy")]struct Pages{files:Vec<(String,Vec<u8>)>,config:crate::captured_raw_file::Config,stop:bool}
#[cfg(feature="native-policy")]impl crate::captured_cache_bytes::OriginalBytesPages for Pages{fn for_each(&self,visit:&mut dyn FnMut(&str,&[u8])->Result<bool,crate::captured_reactive_reads::Failure>)->Result<bool,crate::captured_reactive_reads::Failure>{for(relative,bytes)in &self.files{if !crate::cache_policy::META.select.matches_path(relative)||self.config.policy_path_exempt("cache","",relative){continue}if !visit(relative,bytes)?{return Ok(false)}}Ok(!self.stop)}}
#[cfg(feature="native-policy")]#[test]fn cache_native_data_matches_whole_original_bytes_and_digests_without_source_authority(){use crate::{captured_generator_budget::Budget,captured_raw_policy::Configuration};for case in fixture::CASES{let root=crate::test_scratch::dir(&format!("cache-native-{case}"));let files=fixture::files(case).unwrap();for(relative,bytes)in &files{let file=root.join(relative);std::fs::create_dir_all(file.parent().unwrap()).unwrap();std::fs::write(file,bytes).unwrap();}let mut registry=Registry::default();original::register(&mut registry);let old=crate::run::Engine::new(registry,crate::run::Options{root:root.clone(),lints:vec!["cache".into()],raw:true,no_cache:true,..Default::default()}).unwrap();let expected=old.run_one(old.reg.lints[0].as_ref());let bytes=&files.iter().find(|(r,_)|r=="tools/ci/lint_scopes.toml").unwrap().1;let mut pages=Pages{config:crate::captured_raw_file::Config::capture(Configuration::Captured(bytes)).unwrap(),files,stop:false};pages.files.sort_by(|a,b|a.0.cmp(&b.0));let budget=Budget::new(32*1024*1024).unwrap();let actual=crate::captured_cache_bytes::collect(&pages,&budget,&||Ok(())).unwrap();assert_eq!(actual.sites(),expected.run.sites.as_slice(),"sites {case}");assert_eq!(actual.allow_used(),expected.allow_used.as_slice(),"ALLOW {case}");for used in actual.allow_used(){assert_eq!(actual.allow_digests().get(&used.rel),Some(&crate::captured_raw_file::source_allow_digest(old.tree.get(&used.rel).unwrap())));}pages.stop=true;let budget=Budget::new(32*1024*1024).unwrap();assert!(crate::captured_cache_bytes::collect(&pages,&budget,&||Ok(())).is_err());let budget=Budget::new(32*1024*1024).unwrap();assert!(matches!(crate::captured_cache_bytes::collect(&pages,&budget,&||Err(std::io::Error::from_raw_os_error(1450))),Err(crate::captured_reactive_reads::Failure::Operational(ref e))if e.raw_os_error()==Some(1450)));}}
